command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: BLICK IN DIE SEELE (ZERZAL)
//
// - mehrere Targets, mit Reichweitenprüfung (8 Schritt)
// - gültige Ziele (Zweibeiner, Tiere, Erwachte) = Erfolg
// - zentrale Zweibeiner-Erkennung über Block 2
// - ungültige Ziele (Reichweite, falsches Wesen) = Misserfolg
// - gespeicherte Ziele, kein erneutes Target
// - eine gemeinsame Karte über Block 11
// - roter GM-Makrobutton über Block 11
// - direkte Effektanlage über Block 6
// - alte Effekte nur für denselben Wirkenden ersetzen
// - verarbeitete GM-Anfragen werden auch bei Misserfolg abgeschlossen
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden ||
        !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.Wesen?.match ||
        !globalThis.DSK?.Wesen?.IstZweibeiner ||
        !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Geometrie?.Distanz ||
        !globalThis.DSK?.GMAnfrage?.Speichern ||
        !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen ||
        !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);

        if (!fwMacro?.execute) {
            return ui.notifications.error(
                "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
            );
        }

        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden ||
        !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.Wesen?.match ||
        !DSK_FW?.Wesen?.IstZweibeiner ||
        !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Geometrie?.Distanz ||
        !DSK_FW?.GMAnfrage?.Speichern ||
        !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen ||
        !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework 01.03 wurde nicht vollständig geladen!"
        );
    }

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Blick in die Seele";
    const vollerName = "Blick in die Seele (Zerzal)";
    const ahne = "Zerzal";
    const flagKey = "pendingBlickInDieSeeleZerzal";
    const maxReichweite = 8;

    DSK_FW.EffektEnde.Register(
        "blickInDieSeele",
        vollerName,
        "Der Blick in die Seele endet. Die tiefen Antriebe und Wünsche sind wieder verborgen."
    );

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const ladeActor = async uuid => {
        if (!uuid) return null;

        try {
            const dokument = await fromUuid(uuid);

            return dokument?.documentName === "Token"
                ? dokument.actor
                : dokument || null;
        } catch (error) {
            console.warn(
                "Blick in die Seele: Actor konnte nicht geladen werden.",
                {
                    uuid,
                    error
                }
            );

            return null;
        }
    };

    const findeBlickEffekte = (actor, casterUuid) =>
        (actor?.effects || []).filter(effect =>
            (effect.name || effect.label || "") === vollerName &&
            effect.getFlag("dsk", "isBlickInDieSeele") === true &&
            effect.getFlag("dsk", "casterUuid") === casterUuid
        );

    const raeumeQSAuf = async actor => {
        if (
            actor?.getFlag(
                "world",
                "letzteGabenQS"
            ) !== undefined
        ) {
            await actor.unsetFlag(
                "world",
                "letzteGabenQS"
            );
        }
    };

    const istErlaubtesZiel = actor => {
        if (!actor) return false;

        const istErwachterOderNpc =
            DSK_FW.Effekt.CheckTarget(
                actor,
                "erwachte"
            );

        const istTier =
            DSK_FW.Wesen.match(
                actor,
                [
                    "tier",
                    "tiere",
                    "animal"
                ]
            );

        const istZweibeiner =
            DSK_FW.Wesen.IstZweibeiner(
                actor
            );

        return Boolean(
            istErwachterOderNpc ||
            istTier ||
            istZweibeiner
        );
    };

    // +++ 4 - EFFEKT DIREKT ÜBER BLOCK 6 ++++++++++++++++++++++

    const wendeBlickAn = async ({
        casterActor,
        casterName,
        targetActor,
        qs,
        dauerMinuten
    }) => {
        if (!casterActor || !targetActor) return false;

        const alteEffekte =
            findeBlickEffekte(
                targetActor,
                casterActor.uuid
            );

        if (alteEffekte.length) {
            await targetActor.deleteEmbeddedDocuments(
                "ActiveEffect",
                alteEffekte.map(effect => effect.id)
            );
        }

        const erzeugterEffekt =
            await DSK_FW.Effekt.Anwenden({
                name: vollerName,
                ahne,

                beschreibung:
                    `Das Zerzalkind spürt, was das Ziel besonders antreibt.` +
                    `<br><br><b>Wirkender:</b> ${casterName}` +
                    `<br><b>Wirkungsdauer:</b> ${dauerMinuten} Minuten`,

                gabeZiel: "",
                qs,
                ziel: targetActor,

                duration: {
                    seconds: dauerMinuten * 60,
                    startTime: game.time.worldTime
                },

                flags: {
                    dsk: {
                        isBlickInDieSeele: true,
                        casterUuid: casterActor.uuid,
                        qs
                    }
                }
            });

        if (!erzeugterEffekt) return false;

        return Boolean(
            (erzeugterEffekt.name ||
                erzeugterEffekt.label ||
                "") === vollerName &&

            erzeugterEffekt.getFlag(
                "dsk",
                "isBlickInDieSeele"
            ) === true &&

            erzeugterEffekt.getFlag(
                "dsk",
                "casterUuid"
            ) === casterActor.uuid
        );
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN ++++++++++++++++++++++++++

    const verarbeiteAnfrage = async (
        casterActor,
        daten
    ) => {
        if (
            !casterActor ||
            !daten ||
            !game.user.isGM
        ) {
            return false;
        }

        if (
            daten.casterUuid &&
            daten.casterUuid !== casterActor.uuid
        ) {
            ui.notifications.warn(
                "Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum wirkenden Akteur."
            );

            return false;
        }

        if (
            daten.sceneId &&
            daten.sceneId !== canvas.scene?.id
        ) {
            ui.notifications.warn(
                `Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
            );

            return false;
        }

        const qs =
            Math.max(
                1,
                Math.floor(
                    Number(daten.qs) || 1
                )
            );

        const dauerMinuten =
            qs;

        const casterName =
            daten.casterName ||
            DSK_FW.ResolveTokenName(
                casterActor
            );

        const erfolge = [];

        const misserfolge =
            foundry.utils.deepClone(
                daten.misserfolge || []
            );

        for (const ziel of daten.ziele || []) {
            const targetActor =
                await ladeActor(
                    ziel.actorUuid
                );

            if (!targetActor) {
                misserfolge.push({
                    name:
                        ziel.name ||
                        "Unbekanntes Ziel",

                    grund:
                        "Zielakteur wurde nicht gefunden"
                });

                continue;
            }

            if (!istErlaubtesZiel(targetActor)) {
                misserfolge.push({
                    name:
                        ziel.name ||
                        targetActor.name,

                    grund:
                        "Kein Zweibeiner/Tier/Erwachter"
                });

                continue;
            }

            try {
                const effektErfolgreich =
                    await wendeBlickAn({
                        casterActor,
                        casterName,
                        targetActor,
                        qs,
                        dauerMinuten
                    });

                if (effektErfolgreich) {
                    erfolge.push({
                        name:
                            ziel.name ||
                            DSK_FW.ResolveTokenName(
                                targetActor
                            ),

                        rolle:
                            "Seele ergründet"
                    });
                } else {
                    misserfolge.push({
                        name:
                            ziel.name ||
                            targetActor.name,

                        grund:
                            "Effekt konnte nicht angelegt werden"
                    });
                }
            } catch (error) {
                console.error(
                    "Blick in die Seele: Effektanlage fehlgeschlagen.",
                    {
                        ziel,
                        error
                    }
                );

                misserfolge.push({
                    name:
                        ziel.name ||
                        targetActor.name,

                    grund:
                        "Effektanlage fehlgeschlagen"
                });
            }
        }

        const erfolgreich =
            erfolge.length > 0;

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId:
                daten.messageId,

            gabenName:
                vollerName,

            ahne,

            beschreibung:
                daten.beschreibung ||
                "",

            wirkender:
                casterName,

            ziele:
                erfolge,

            misserfolge,

            dauerText:
                `${dauerMinuten} Minute(n) (${qs} QS × 1 Min.)`,

            erfolgreich
        });

        if (!erfolgreich) {
            ui.notifications.error(
                "Luna sagt 🌙: Blick in die Seele konnte auf kein Ziel angewendet werden!"
            );

            return true;
        }

        ui.notifications.info(
            `Luna sagt 🌙: Blick in die Seele wurde auf ${erfolge.length} Ziel(e) angewendet.`
        );

        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen =
            DSK_FW.GMAnfrage.Finden(
                flagKey
            );

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten =
                    DSK_FW.GMAnfrage.Lesen(
                        anfrageActor,
                        flagKey
                    );

                if (!daten) continue;

                if (
                    await verarbeiteAnfrage(
                        anfrageActor,
                        daten
                    )
                ) {
                    await DSK_FW.GMAnfrage.Loeschen(
                        anfrageActor,
                        flagKey
                    );
                }
            }

            return;
        }
    }

    // +++ 7 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor =
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor =>
                    actor?.getFlag(
                        "world",
                        "letzteGabenQS"
                    ) !== undefined
                ) ||

            game.actors.find(actor =>
                actor.getFlag(
                    "world",
                    "letzteGabenQS"
                ) !== undefined
            ) ||

            null;
    }

    if (!casterActor) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!"
        );
    }

    if (
        !game.user.isGM &&
        !casterActor.isOwner
    ) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken =
        DSK_FW.Token.Finde(
            casterActor
        );

    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Der Wirkende braucht einen Token auf der Szene!"
        );
    }

    const casterName =
        DSK_FW.ResolveTokenName(
            casterActor
        );

    const qs =
        DSK_FW.QS.Ermitteln({
            actor:
                casterActor,

            gabenName,

            suchbegriffe: [
                "Blick in die Seele Probe",
                "Blick in die Seele"
            ],

            testDataObj:
                typeof testData !== "undefined"
                    ? testData
                    : null,

            fallback:
                0,

            protokollieren:
                true
        });

    if (qs <= 0) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    const dauerMinuten =
        qs;

    const dauerText =
        `${dauerMinuten} Minute(n) (${qs} QS × 1 Min.)`;

    // +++ 8 - TARGETS PRÜFEN +++++++++++++++++++++++++++++++++++

    const targets =
        Array.from(
            game.user.targets
        );

    if (!targets.length) {
        await raeumeQSAuf(
            casterActor
        );

        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!"
        );
    }

    const gueltigeZiele = [];
    const misserfolge = [];

    for (const targetToken of targets) {
        const targetActor =
            targetToken?.actor;

        const targetName =
            targetToken?.name ||
            targetActor?.name ||
            "Unbekanntes Target";

        if (!targetActor) {
            misserfolge.push({
                name:
                    targetName,

                grund:
                    "Kein gültiger Akteur"
            });

            continue;
        }

        const fehler = [];

        const distanz =
            DSK_FW.Geometrie.Distanz(
                casterToken,
                targetToken
            );

        if (distanz > maxReichweite) {
            fehler.push(
                `${Math.ceil(distanz - maxReichweite)} Schritt zu weit`
            );
        }

        if (!istErlaubtesZiel(targetActor)) {
            fehler.push(
                "Kein Zweibeiner/Tier/Erwachter"
            );
        }

        if (fehler.length) {
            misserfolge.push({
                name:
                    targetName,

                grund:
                    fehler.join(" + ")
            });

            continue;
        }

        gueltigeZiele.push({
            actorUuid:
                targetActor.uuid,

            tokenId:
                targetToken.id,

            tokenUuid:
                targetToken.document?.uuid ||
                targetToken.uuid ||
                null,

            name:
                targetName
        });
    }

    // +++ 9 - KEIN GÜLTIGES ZIEL ++++++++++++++++++++++++++++++

    const beschreibung =
        `Behält das Zerzalkind sein Ziel eine Minute im Blick, kann es spüren, was sein Ziel besonders antreibt.` +
        `<br><br><b>Zielkategorie:</b> Zweibeiner, Tiere, Erwachte` +
        `<br><b>Reichweite beim Wirken:</b> ${maxReichweite} Schritt`;

    if (!gueltigeZiele.length) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName:
                vollerName,

            ahne,

            beschreibung,

            wirkender:
                casterName,

            ziele:
                [],

            misserfolge,

            dauerText,

            gmBereich:
                false,

            angewendet:
                true,

            erfolgreich:
                false,

            anfragenderUserId:
                game.user.id
        });

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    // +++ 10 - GEMEINSAME KARTE ++++++++++++++++++++++++++++++++

    const gmLink =
        DSK_FW.GabenUI.GMMakroButton(
            macroUuid
        );

    const nachricht =
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName:
                vollerName,

            ahne,

            beschreibung,

            wirkender:
                casterName,

            ziele:
                gueltigeZiele.map(ziel => ({
                    name:
                        ziel.name,

                    rolle:
                        "Seele ergründet"
                })),

            misserfolge,

            dauerText,
            gmLink,

            gmBereich:
                !game.user.isGM,

            anfragenderUserId:
                game.user.id
        });

    if (!nachricht) {
        return ui.notifications.error(
            "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
        );
    }

    // +++ 11 - ANFRAGEDATEN ++++++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid:
            casterActor.uuid,

        casterName,
        qs,
        dauerMinuten,

        ziele:
            gueltigeZiele,

        misserfolge,
        beschreibung,

        sceneId:
            canvas.scene?.id ||
            null,

        requestedByUserId:
            game.user.id,

        messageId:
            nachricht.id,

        macroUuid
    };

    // +++ 12 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(
            casterActor,
            anfrageDaten
        );

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    await DSK_FW.GMAnfrage.Speichern(
        casterActor,
        flagKey,
        anfrageDaten
    );

    // +++ 13 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(
        casterActor
    );

    ui.notifications.info(
        "Luna sagt 🌙: Blick in die Seele wurde bei der Spielleitung beantragt."
    );

}).call(this);
